+      border-radius: 22px;
+      padding: 1.35rem;
+    }
+
+    .question-title {
+      display: flex;
+      gap: 0.8rem;
+      align-items: flex-start;
+      margin: 0 0 0.6rem;
+      font-size: 1.12rem;
