      --bg: #0c111d;
      --panel: #111827;
      --panel-soft: #172033;
      --text: #eef2ff;
      --muted: #a7b0c5;
      --accent: #7c3aed;
      --accent-strong: #a78bfa;
      --border: rgba(167, 139, 250, 0.22);
      --success: #34d399;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.34), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 30rem),
        var(--bg);
      display: grid;
      place-items: center;
      padding: 2rem;
    }

    main {
      width: min(100%, 820px);
      background: linear-gradient(145deg, rgba(17, 24, 39, 0.94), rgba(12, 17, 29, 0.96));
      border: 1px solid var(--border);
      border-radius: 28px;
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 4vw, 3rem);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      color: var(--accent-strong);
      font-size: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.16em;
      margin: 0 0 0.75rem;
      text-transform: uppercase;
    }

    h1 {
      font-size: clamp(2rem, 5vw, 3.5rem);
      line-height: 1;
      margin: 0;
    }

    .intro {
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.6;
      margin: 1rem 0 2rem;
      max-width: 62ch;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      background: rgba(23, 32, 51, 0.78);
      border: 1px solid rgba(148, 163, 184, 0.18);
      border-radius: 22px;
      padding: 1.35rem;
    }

    .question-title {
      display: flex;
      gap: 0.8rem;
      align-items: flex-start;
      margin: 0 0 0.6rem;
      font-size: 1.12rem;
    }

    .question-number {
      display: inline-grid;
      place-items: center;
      flex: 0 0 2rem;
      width: 2rem;
      height: 2rem;
      border-radius: 999px;
      background: rgba(124, 58, 237, 0.22);
      color: var(--accent-strong);
      font-size: 0.9rem;
      font-weight: 800;
    }

    .help-text {
      margin: 0 0 1rem 2.8rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
      gap: 0.75rem;
      margin-top: 1rem;
    }

    label {
      position: relative;
      display: flex;
      align-items: center;
      gap: 0.7rem;
      min-height: 3.3rem;
      padding: 0.85rem 0.95rem;
      border: 1px solid rgba(148, 163, 184, 0.16);
      border-radius: 16px;
      background: rgba(15, 23, 42, 0.72);
      cursor: pointer;
      transition: border-color 180ms ease, transform 180ms ease, background 180ms ease;
    }

    label:hover {
      border-color: rgba(167, 139, 250, 0.58);
      background: rgba(30, 41, 59, 0.86);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.1rem;
      height: 1.1rem;
      margin: 0;
      accent-color: var(--accent);
    }

    label:has(input:checked) {
      border-color: rgba(167, 139, 250, 0.8);
      background: rgba(124, 58, 237, 0.18);
    }

    button {
      justify-self: start;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.5rem;
      color: white;
      background: linear-gradient(135deg, var(--accent), #2563eb);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 16px 36px rgba(124, 58, 237, 0.34);
      transition: transform 180ms ease, box-shadow 180ms ease;
    }

    button:hover {
      transform: translateY(-2px);
      box-shadow: 0 20px 44px rgba(124, 58, 237, 0.44);
    }

    .result {
      min-height: 1.5rem;
      color: var(--success);
      font-weight: 700;
      margin: 0.25rem 0 0;
    }
  </style>
</head>
<body>
  <main>
    <p class="eyebrow">Multi-select quiz</p>
    <h1>Computer Languages</h1>
    <p class="intro">Choose every answer that applies for each question, then submit to see how many selections you made.</p>

    <form id="languageQuiz">
      <div class="form-field">
        <h2 class="question-title">
          <span class="question-number">1</span>
          Which of these are commonly used for web development?
        </h2>
        <p class="help-text">Select all languages that can run in, style, or power websites and web apps.</p>
        <div class="choices">
          <label><input type="checkbox" name="web" value="JavaScript"> JavaScript</label>
          <label><input type="checkbox" name="web" value="HTML"> HTML</label>
          <label><input type="checkbox" name="web" value="CSS"> CSS</label>
          <label><input type="checkbox" name="web" value="Python"> Python</label>
        </div>
      </div>

      <div class="form-field">
        <h2 class="question-title">
          <span class="question-number">2</span>
          Which languages are known for systems programming?
        </h2>
        <div class="choices">
          <label><input type="checkbox" name="systems" value="C"> C</label>
          <label><input type="checkbox" name="systems" value="Rust"> Rust</label>
          <label><input type="checkbox" name="systems" value="Go"> Go</label>
          <label><input type="checkbox" name="systems" value="Ruby"> Ruby</label>
        </div>
      </div>

      <div class="form-field">
        <h2 class="question-title">
          <span class="question-number">3</span>
          Which languages are often used for data science or analytics?
        </h2>
        <div class="choices">
          <label><input type="checkbox" name="data" value="Python"> Python</label>
          <label><input type="checkbox" name="data" value="R"> R</label>
          <label><input type="checkbox" name="data" value="SQL"> SQL</label>
          <label><input type="checkbox" name="data" value="Swift"> Swift</label>
        </div>
      </div>

      <button type="submit">Submit answers</button>
      <p class="result" id="result" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const quiz = document.querySelector("#languageQuiz");
    const result = document.querySelector("#result");

    quiz.addEventListener("submit", (event) => {
      event.preventDefault();

      const checkedCount = quiz.querySelectorAll("input[type='checkbox']:checked").length;
      const questionCount = quiz.querySelectorAll(".form-field").length;
      result.textContent = `Submitted ${checkedCount} selected answer${checkedCount === 1 ? "" : "s"} across ${questionCount} questions.`;
    });
  </script>
</body>
</html>
